const navigation: { id: View; icon: LucideIcon; key: string; role: 'student' | 'organizer' | 'admin' }[] = [
  { id: 'discover', icon: CalendarDays, key: 'home', role: 'student' },
  { id: 'tickets', icon: Ticket, key: 'tickets', role: 'student' },
  { id: 'create', icon: Plus, key: 'create', role: 'organizer' },
  { id: 'checkin', icon: ScanLine, key: 'checkin', role: 'organizer' },
  { id: 'attendees', icon: Users, key: 'attendees', role: 'organizer' },
  { id: 'approvals', icon: ShieldCheck, key: 'approvals', role: 'admin' },
  { id: 'analytics', icon: ChartNoAxesCombined, key: 'analytics', role: 'admin' },
]

export function UniEventApp() {
  const { theme, setTheme } = useTheme()
  const [mounted, setMounted] = useState(false)
  const [view, setView] = useState<View>('discover')

  useEffect(() => setMounted(true), [])
  const [locale, setLocale] = useState<Locale>('ar')
  const [category, setCategory] = useState('all')
  const [search, setSearch] = useState('')
  const [selected, setSelected] = useState<EventItem | null>(null)
  const [registered, setRegistered] = useState<number[]>([])
  const [ticketTab, setTicketTab] = useState('upcoming')
  const [chatOpen, setChatOpen] = useState(false)
  const [chatInput, setChatInput] = useState('')
  const [chatMessages, setChatMessages] = useState<{ role: 'user' | 'assistant'; text: string }[]>([])
  const [chatLoading, setChatLoading] = useState(false)
  const [mobileNav, setMobileNav] = useState(false)
  const [toast, setToast] = useState('')
  const [ratingEvent, setRatingEvent] = useState<EventItem | null>(null)
  const [rating, setRating] = useState(5)
  const t = copy[locale]
  const ar = locale === 'ar'
  const role = navigation.find((item) => item.id === view)?.role ?? 'student'

  const notify = (message: string) => {
    setToast(message)
    window.setTimeout(() => setToast(''), 3000)
  }
  const navigate = (destination: View) => {
    setView(destination)
    setMobileNav(false)
    window.scrollTo({ top: 0, behavior: 'smooth' })
  }
  const filteredEvents = useMemo(() => events.filter((event) => {
    const query = `${event.title} ${event.titleEn} ${event.category} ${event.categoryEn} ${event.place} ${event.placeEn}`.toLocaleLowerCase()
    return (category === 'all' || event.category === category) && query.includes(search.trim().toLocaleLowerCase())
  }), [category, search])

  async function requestAI(kind: 'chat' | 'description', text: string) {
    const response = await fetch('/api/ai', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ kind, text, language: locale }),
    })
    const result = await response.json()
    if (!response.ok || typeof result.text !== 'string') throw new Error(result.error || 'Request failed')
    return result.text as string
  }

  async function sendChat(message = chatInput) {
    const prompt = message.trim()
    if (!prompt || chatLoading) return
    setChatInput('')
    setChatMessages((current) => [...current, { role: 'user', text: prompt }])
    setChatLoading(true)
    try {
      const answer = await requestAI('chat', prompt)
      setChatMessages((current) => [...current, { role: 'assistant', text: answer }])
    } catch (error) {
      const reply = error instanceof Error ? error.message : t.aiError
      setChatMessages((current) => [...current, { role: 'assistant', text: reply }])
    } finally { setChatLoading(false) }
  }

  function registerEvent(event: EventItem) {
    setRegistered((current) => current.includes(event.id) ? current : [...current, event.id])
    notify(t.confirmed)
  }

  const pageTitle = navigation.find((item) => item.id === view)
  return <div className="app-frame" dir={ar ? 'rtl' : 'ltr'}>
    <aside className={`sidebar ${mobileNav ? 'sidebar-open' : ''}`} aria-label={t.navigation}>
      <button className="brand-lockup" onClick={() => navigate('discover')} aria-label="UniEvent"><span className="brand-mark"><GraduationCap /></span><span><strong>UniEvent</strong><small>{t.sidebarSubtitle}</small></span></button>
      <div className="sidebar-label">{t.workspace}</div>
      <nav className="sidebar-nav">{navigation.map(({ id, icon: Icon, key }) => <button key={id} className={`nav-link ${view === id ? 'nav-link-active' : ''}`} onClick={() => navigate(id)}><Icon /><span>{t[key as keyof typeof t]}</span>{id === 'approvals' && <span className="nav-count">2</span>}</button>)}</nav>
      <div className="sidebar-spacer" />
      <div className="sidebar-tip"><span className="tip-icon"><Sparkles /></span><strong>{t.aiPowered}</strong><p>{t.smartText}</p></div>
      <div className="sidebar-footer"><span className="avatar">ر</span><span className="user-meta"><strong>{ar ? 'رغد أحمد' : 'Raghad Ahmed'}</strong><small>{t[role === 'student' ? 'studentRole' : role === 'organizer' ? 'organizerRole' : 'adminRole']}</small></span><button className="icon-button muted-button" aria-label={t.profile}><MoreHorizontal /></button></div>
    </aside>
    {mobileNav && <button className="sidebar-scrim" aria-label={t.close} onClick={() => setMobileNav(false)} />}
    <div className="main-column">
      <header className="topbar"><div className="topbar-start"><button className="icon-button mobile-menu-button" onClick={() => setMobileNav((open) => !open)} aria-label={t.navigation}><Menu /></button><div className="breadcrumb"><span>UniEvent</span><ChevronLeft /><strong>{t[pageTitle?.key as keyof typeof t] ?? t.home}</strong></div></div><div className="topbar-actions"><label className="header-search"><Search /><input aria-label={t.search} placeholder={t.search} value={search} onChange={(event) => setSearch(event.target.value)} onKeyDown={(event) => { if (event.key === 'Enter') navigate('discover') }} /></label><button className="icon-button" onClick={() => setLocale(ar ? 'en' : 'ar')} aria-label={t.language}><Languages /></button><button className="icon-button" onClick={() => setTheme(theme === 'dark' ? 'light' : 'dark')} aria-label={t.theme}>{mounted && theme === 'dark' ? <Sun /> : <Moon />}</button><button className="icon-button notification-button" onClick={() => notify(t.notificationEmpty)} aria-label={t.notifications}><Bell /><span /></button><span className="topbar-divider" /><button className="topbar-profile" aria-label={t.myAccount}><span className="avatar avatar-small">ر</span><span className="profile-copy"><strong>{ar ? 'رغد أحمد' : 'Raghad Ahmed'}</strong><small>{t[role === 'student' ? 'studentRole' : role === 'organizer' ? 'organizerRole' : 'adminRole']}</small></span><ChevronDown /></button></div></header>
      <main className="main-content" id="main-content">
        {view === 'discover' && <HomePage t={t} ar={ar} search={search} setSearch={setSearch} category={category} setCategory={setCategory} found={filteredEvents} registered={registered} onSelect={setSelected} onRegister={registerEvent} onNavigate={navigate} />}
        {view === 'tickets' && <TicketsPage t={t} ar={ar} registered={registered} activeTab={ticketTab} setActiveTab={setTicketTab} onRate={setRatingEvent} onToast={notify} onBrowse={() => navigate('discover')} />}
        {view === 'create' && <CreatePage t={t} ar={ar} onToast={notify} generate={(text: string) => requestAI('description', text)} />}
        {view === 'checkin' && <CheckinPage t={t} ar={ar} onToast={notify} />}
        {view === 'attendees' && <AttendeesPage t={t} ar={ar} onToast={notify} />}
        {view === 'approvals' && <ApprovalsPage t={t} ar={ar} onToast={notify} />}
        {view === 'analytics' && <AnalyticsPage t={t} ar={ar} />}
      </main>
      <footer className="site-footer"><span>{t.footer}</span><span>{t.footerData}</span><span>{ar ? 'المساعدة والدعم' : 'Help & support'}</span></footer>
    </div>
    <button className="chat-fab" onClick={() => setChatOpen(true)} aria-label={t.assistant}><MessageCircle /><span className="chat-sparkle"><Sparkles /></span></button>
    {chatOpen && <ChatPanel t={t} ar={ar} messages={chatMessages} input={chatInput} setInput={setChatInput} loading={chatLoading} onSend={sendChat} onClose={() => setChatOpen(false)} />}
    {selected && <EventDialog event={selected} t={t} ar={ar} registered={registered.includes(selected.id)} onClose={() => setSelected(null)} onRegister={() => registerEvent(selected)} />}
    {ratingEvent && <RatingDialog event={ratingEvent} t={t} ar={ar} rating={rating} setRating={setRating} onClose={() => setRatingEvent(null)} onSubmit={() => { setRatingEvent(null); notify(t.feedbackSent) }} />}
    {toast && <div className="toast-message" role="status"><CircleCheck />{toast}</div>}
  </div>
}

function PageHeader({ eyebrow, title, description, action }: { eyebrow: string; title: string; description: string; action?: React.ReactNode }) {
  return <div className="page-heading"><div><div className="eyebrow"><span className="eyebrow-dot" />{eyebrow}</div><h1>{title}</h1><p>{description}</p></div>{action}</div>
}
function Metric({ icon: Icon, label, value, change }: { icon: LucideIcon; label: string; value: string; change: string }) {
  return <div className="stat-card"><span className="stat-icon"><Icon /></span><div className="stat-info"><span>{label}</span><strong>{value}</strong><small><TrendingUp />{change}</small></div></div>
}
function HomePage({ t, ar, search, setSearch, category, setCategory, found, registered, onSelect, onRegister, onNavigate }: any) {
  const categoryItems = [
    { id: 'all', label: t.all, icon: Sparkles }, { id: 'تقنية', label: t.technology, icon: LayoutDashboard },
    { id: 'ريادة الأعمال', label: t.business, icon: TrendingUp }, { id: 'ثقافة وترفيه', label: t.arts, icon: Star }, { id: 'رياضة', label: t.sports, icon: Activity },
  ]
  return <div className="page-stack">
    <div className="page-heading"><div><div className="eyebrow"><span className="eyebrow-dot" />{t.today}</div><h1>{t.greeting}</h1><p>{t.subtitle}</p></div><button className="button-outline" onClick={() => onNavigate('tickets')}><Ticket />{t.tickets}</button></div>
    <section className="hero-banner"><div className="hero-shade" /><div className="hero-content"><span className="hero-eyebrow"><Sparkles />{t.heroEyebrow}</span><h2>{t.heroTitle}</h2><p>{t.heroText}</p><button className="hero-cta" onClick={() => document.getElementById('events-list')?.scrollIntoView({ behavior: 'smooth' })}>{t.explore}<ArrowLeft /></button></div><div className="hero-meta"><span><CalendarDays />{ar ? '٢٣ — ٢٧ أكتوبر' : 'Oct 23–27'}</span><span className="hero-separator" /><span><MapPin />{ar ? 'الحرم الجامعي' : 'University campus'}</span></div><div className="hero-count"><strong>{ar ? '١٨' : '18'}</strong><span>{t.events}</span></div></section>
    <section className="stats-strip"><Metric icon={CalendarCheck} label={t.totalEvents} value={ar ? '١٨' : '18'} change="+٢٤٪" /><Metric icon={Users} label={t.registeredStudents} value={ar ? '١٬٢٨٠' : '1,280'} change="+١٨٪" /><Metric icon={Ticket} label={t.attendedEvents} value={ar ? '٠٣' : '03'} change={t.thisWeek} /><div className="stats-callout"><span className="callout-icon"><Sparkles /></span><div><strong>{t.smartSummary}</strong><p>{ar ? 'زيادة الورش العملية يوم الخميس قد ترفع التسجيل بنسبة ١٨٪.' : 'Hands-on Thursday workshops may boost registrations by 18%.'}</p></div></div></section>
    <section className="recommendation-panel"><div className="recommendation-top"><div className="recommendation-title"><span className="ai-icon"><Sparkles /></span><div><div className="recommendation-label">{t.aiPowered}</div><h2>{t.smart}</h2></div></div><Badge variant="secondary" className="ai-badge"><Sparkles />{t.reason}</Badge></div><p className="recommendation-copy">{t.smartText}</p><div className="recommendation-event"><span className="recommendation-event-icon"><Lightbulb /></span><div className="recommendation-event-copy"><strong>{ar ? events[0].title : events[0].titleEn}</strong><span><CalendarDays />{ar ? events[0].date : events[0].dateEn}<i /><MapPin />{ar ? events[0].place : events[0].placeEn}</span></div><button className="recommendation-action" onClick={() => onSelect(events[0])}>{t.details}<ArrowLeft /></button></div><div className="recommendation-reason"><Sparkles />{t.reason}: {t.suggestion}</div></section>
    <section className="events-section" id="events-list"><div className="section-heading"><div><div className="eyebrow"><span className="eyebrow-dot" />{t.thisWeek}</div><h2>{t.happening}</h2></div><button className="text-button" onClick={() => { setCategory('all'); setSearch('') }}>{t.seeAll}<ArrowLeft /></button></div>
      <div className="event-filters" role="group" aria-label={t.labels}>{categoryItems.map(({ id, label, icon: Icon }: any) => <button key={id} className={`filter-chip ${category === id ? 'filter-chip-active' : ''}`} onClick={() => setCategory(id)}><Icon />{label}</button>)}<span className="filter-spacer" /><span className="result-count">{found.length} {t.events}</span></div>
      {found.length ? <div className="events-grid">{found.map((event: EventItem) => <EventCard key={event.id} event={event} t={t} ar={ar} registered={registered.includes(event.id)} onSelect={onSelect} onRegister={onRegister} />)}</div> : <div className="empty-state"><Search /><strong>{t.searchEmpty}</strong><span>{t.noResults}</span><button className="text-button" onClick={() => { setSearch(''); setCategory('all') }}>{t.reset}</button></div>}
    </section><div className="bottom-promo"><span className="promo-icon"><Sparkles /></span><div><strong>{ar ? 'كوني جزءاً من مجتمع الجامعة' : 'Join the campus community'}</strong><p>{t.invitationText}</p></div><button className="button-outline" onClick={() => onNavigate('tickets')}>{t.myTickets}<ArrowLeft /></button></div>
  </div>
}
function EventCard({ event, t, ar, registered, onSelect, onRegister }: any) {
  const Icon = event.icon
  const percent = Math.round(event.registered / event.capacity * 100)
  return <Card className={`event-card tone-${event.tone}`}><button className="event-cover" onClick={() => onSelect(event)} aria-label={`${t.details}: ${ar ? event.title : event.titleEn}`}><div className="cover-pattern" /><div className="cover-topline"><Badge variant="secondary">{ar ? event.category : event.categoryEn}</Badge>{event.recommended && <span className="card-ai-tag"><Sparkles />{t.aiPowered}</span>}<span className="cover-save"><Bookmark /></span></div><span className="cover-icon"><Icon /></span><span className="cover-date"><CalendarDays />{ar ? event.date : event.dateEn}</span></button><div className="event-card-body"><button className="event-title-button" onClick={() => onSelect(event)}><h3>{ar ? event.title : event.titleEn}</h3></button><div className="event-card-place"><MapPin />{ar ? event.place : event.placeEn}</div><div className="event-card-meta"><span><Clock3 />{ar ? event.time : event.dateEn}</span><span><Users />{event.registered} {t.registeredCount}</span></div><div className="capacity-row"><span>{t.capacity} {percent}٪</span><span>{event.capacity - event.registered} {t.seats}</span></div><Progress value={percent} className="capacity-progress" aria-label={`${t.capacity}: ${percent}%`} /><div className="event-card-actions"><button className="button-primary card-register" onClick={() => onRegister(event)} disabled={registered}>{registered ? <><Check />{t.registered}</> : <>{t.register}<ArrowLeft /></>}</button><button className="icon-button card-detail" onClick={() => onSelect(event)} aria-label={t.details}><ArrowUpLeft /></button></div></div></Card>
}
function EventDialog({ event, t, ar, registered, onClose, onRegister }: any) {
  const Icon = event.icon
  return <div className="modal-backdrop" onMouseDown={(event) => { if (event.target === event.currentTarget) onClose() }}><section className="event-modal" role="dialog" aria-modal="true" aria-labelledby="event-title"><button className="modal-close" onClick={onClose} aria-label={t.close}><X /></button><div className={`modal-art tone-${event.tone}`}><div className="cover-pattern" /><Icon /><span>{ar ? event.category : event.categoryEn}</span></div><div className="modal-content"><span className="eyebrow"><Sparkles />{t.eventDetails}</span><h2 id="event-title">{ar ? event.title : event.titleEn}</h2><p className="modal-description">{ar ? t.detailsText : 'Meet campus innovators for inspiring discussions, practical sessions, and student-led projects.'}</p><div className="detail-grid"><div><CalendarDays /><span>{ar ? event.date : event.dateEn}<small>{ar ? event.time : '10:00 AM'}</small></span></div><div><MapPin /><span>{ar ? event.place : event.placeEn}<small>{t.mapHint}</small></span></div><div><Users /><span>{event.capacity - event.registered} {t.seats}<small>{event.registered} {t.registeredCount}</small></span></div><div><Building2 /><span>{ar ? 'فريق فعاليات الجامعة' : 'University Events Team'}<small>{t.organizer}</small></span></div></div><div className="map-placeholder"><div className="map-grid"><MapPin /></div><div><strong>{t.campusMap}</strong><span>{ar ? 'مبنى الابتكار، الدور الأرضي' : 'Innovation building · Ground floor'}</span></div><button className="icon-button" aria-label={t.openMap}><ExternalLink /></button></div><button className="button-primary modal-register" onClick={onRegister} disabled={registered}>{registered ? <><CheckCheck />{t.confirmed}</> : <><Ticket />{t.oneClick}</>}</button></div></section></div>
}
function TicketsPage({ t, ar, registered, activeTab, setActiveTab, onRate, onToast, onBrowse }: any) {
  const upcoming = events.filter((event) => registered.includes(event.id))
  const past = [events[1]]
  return <div className="page-stack"><PageHeader eyebrow={t.studentRole} title={t.ticketsTitle} description={t.ticketsHint} /><div className="ticket-summary-row"><Summary icon={Ticket} number={ar ? String(upcoming.length).padStart(2, '0') : String(upcoming.length)} label={t.upcomingTickets} /><Summary icon={FileText} number={ar ? '٠١' : '01'} label={t.certificates} /><Summary icon={Star} number={ar ? '٠٣' : '03'} label={t.attendedEvents} /></div><Tabs value={activeTab} onValueChange={setActiveTab}><TabsList className="page-tabs"><TabsTrigger value="upcoming">{t.upcoming}<span>{upcoming.length}</span></TabsTrigger><TabsTrigger value="past">{t.past}<span>1</span></TabsTrigger></TabsList><TabsContent value="upcoming" className="ticket-list">{upcoming.length ? upcoming.map((event) => <TicketCard key={event.id} event={event} t={t} ar={ar} onToast={onToast} />) : <div className="empty-state ticket-empty"><span className="empty-art"><Ticket /></span><strong>{t.noTickets}</strong><span>{t.ticketsHint}</span><button className="button-primary" onClick={onBrowse}>{t.browse}<ArrowLeft /></button></div>}</TabsContent><TabsContent value="past" className="ticket-list"><PastEvent event={past[0]} t={t} ar={ar} onRate={() => onRate(past[0])} onToast={onToast} /></TabsContent></Tabs><div className="certificate-note"><span><ShieldCheck /></span><div><strong>{t.qrValid}</strong><p>{t.qrInstructions}</p></div></div></div>
}
function Summary({ icon: Icon, number, label }: { icon: LucideIcon; number: string; label: string }) { return <div className="ticket-summary-card"><Icon /><strong>{number}</strong><span>{label}</span></div> }
function TicketCard({ event, t, ar, onToast }: any) {
  return <Card className="digital-ticket"><div className={`ticket-colorbar tone-${event.tone}`} /><div className="ticket-main"><div className="ticket-heading"><span className="ticket-status"><span />{t.registrationOpen}</span><span className="ticket-code">UE-2048</span></div><h3>{ar ? event.title : event.titleEn}</h3><div className="ticket-meta"><span><CalendarDays />{ar ? event.date : event.dateEn}</span><span><Clock3 />{ar ? event.time : '10:00 AM'}</span><span><MapPin />{ar ? event.place : event.placeEn}</span></div><div className="ticket-perforation"><span /><i /><span /></div><div className="ticket-footer"><div className="ticket-owner"><span className="avatar avatar-small">ر</span><span><small>{t.student}</small><strong>{ar ? 'رغد أحمد' : 'Raghad Ahmed'}</strong></span></div><div><small>{t.studentId}</small><strong>2024012048</strong></div><button className="button-outline" onClick={() => onToast(t.downloaded)}><Download />{t.download}</button></div></div><div className="ticket-qr"><QRCodeSVG value={`unievent://ticket/UE-2048/${event.id}`} size={112} level="M" includeMargin fgColor="#1e3a8a" bgColor="transparent" /><span>{t.qrValid}</span></div></Card>
}
function PastEvent({ event, t, ar, onRate, onToast }: any) { return <Card className="past-event-card"><span className="past-event-icon"><FileText /></span><div className="past-event-copy"><span className="eyebrow">{t.attendedEvents}</span><h3>{ar ? 'هاكاثون الحلول المستدامة' : 'Sustainable Solutions Hackathon'}</h3><p><CalendarDays />{ar ? '١٥ سبتمبر ٢٠٢٦' : 'Sep 15, 2026'}<i /><Star />{t.noRatings}</p></div><div className="past-event-actions"><button className="button-outline" onClick={() => onToast(t.downloaded)}><Download />{t.download}</button><button className="button-primary" onClick={onRate}><Star />{t.rate}</button></div></Card> }
function RatingDialog({ event, t, ar, rating, setRating, onClose, onSubmit }: any) { return <div className="modal-backdrop" onMouseDown={(e) => { if (e.target === e.currentTarget) onClose() }}><section className="rating-modal" role="dialog" aria-modal="true" aria-labelledby="rating-title"><button className="modal-close" onClick={onClose} aria-label={t.close}><X /></button><div className="rating-modal-icon"><Heart /></div><span className="eyebrow">{t.feedback}</span><h2 id="rating-title">{t.rate}</h2><p>{ar ? event.title : event.titleEn}</p><div className="rating-picker" role="radiogroup" aria-label={t.rating}>{[1,2,3,4,5].map((value) => <button key={value} role="radio" aria-checked={rating === value} aria-label={`${value} ${t.stars}`} className={value <= rating ? 'star-selected' : ''} onClick={() => setRating(value)}><Star fill="currentColor" /></button>)}</div><label className="form-field"><span>{t.feedback}</span><textarea placeholder={t.feedbackPrompt} rows={3} /></label><button className="button-primary rating-submit" onClick={onSubmit}><Send />{t.sendRating}</button></section></div> }

function CreatePage({ t, ar, onToast, generate }: any) {
  const [step, setStep] = useState(0)
  const [title, setTitle] = useState('')
  const [category, setCategory] = useState('')
  const [idea, setIdea] = useState('')
  const [capacity, setCapacity] = useState('120')
  const [date, setDate] = useState('2026-10-23')
  const [time, setTime] = useState('10:00')
  const [place, setPlace] = useState('')
  const [description, setDescription] = useState('')
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState('')
  const steps = [t.step1, t.step2, t.step3]
  const createDescription = async () => {
    if (!title.trim()) { setError(t.titleRequired); return }
    setLoading(true); setError('')
    try { setDescription(await generate(`${title}\nCategory: ${category}\nIdea: ${idea || 'A welcoming, practical university event.'}`)); onToast(t.descriptionGenerated) }
    catch (error) { setError(error instanceof Error ? error.message : t.formError) } finally { setLoading(false) }
  }
  const continueStep = () => { if (!title.trim()) { setError(t.titleRequired); return } setError(''); setStep((current) => Math.min(2, current + 1)) }
  return <div className="page-stack"><PageHeader eyebrow={t.organizerTools} title={t.createTitle} description={t.createSubtitle} action={<button className="button-outline" onClick={() => onToast(t.draftSaved)}><Bookmark />{t.saveDraft}</button>} /><div className="wizard-shell"><div className="wizard-main"><div className="wizard-stepper" aria-label={`${t.step1}: ${step + 1} / 3`}>{steps.map((label, index) => <div key={label} className={`wizard-step ${step === index ? 'step-active' : step > index ? 'step-done' : ''}`}><span>{step > index ? <Check /> : `0${index + 1}`}</span><div><strong>{label}</strong><small>{ar ? `الخطوة 0${index + 1}` : `Step 0${index + 1}`}</small></div>{index < 2 && <i />}</div>)}</div><div className="wizard-form"><div className="wizard-form-heading"><div className="eyebrow"><span className="eyebrow-dot" />{ar ? `الخطوة 0${step + 1} من ٠٣` : `Step 0${step + 1} of 03`}</div><h2>{steps[step]}</h2><p>{t.draftInfo}</p></div>
    {step === 0 && <div className="form-fields"><label className="form-field"><span>{t.eventName} <b>*</b></span><input value={title} onChange={(e) => setTitle(e.target.value)} placeholder={t.eventNamePlaceholder} required /></label><label className="form-field"><span>{t.category} <b>*</b></span><select value={category} onChange={(e) => setCategory(e.target.value)}><option value="">{t.chooseCategory}</option>{t.categoryOption.map((item: string) => <option value={item} key={item}>{item}</option>)}</select></label><label className="form-field full-width"><span>{t.idea}</span><textarea value={idea} onChange={(e) => setIdea(e.target.value)} placeholder={t.ideaPlaceholder} rows={4} /></label></div>}
    {step === 1 && <div className="form-fields"><label className="form-field"><span>{t.eventDateLabel} <b>*</b></span><input type="date" value={date} onChange={(e) => setDate(e.target.value)} /></label><label className="form-field"><span>{t.time} <b>*</b></span><input type="time" value={time} onChange={(e) => setTime(e.target.value)} /></label><label className="form-field"><span>{t.venue} <b>*</b></span><input value={place} onChange={(e) => setPlace(e.target.value)} placeholder={t.venuePlaceholder} /></label><label className="form-field"><span>{t.capacityLabel} <b>*</b></span><input type="number" min="1" max="10000" value={capacity} onChange={(e) => setCapacity(e.target.value)} /></label><div className="free-event-toggle"><span className="free-icon"><Check /></span><div><strong>{t.free}</strong><span>{t.freeForStudents}</span></div><span className="switch-on"><i /></span></div></div>}
    {step === 2 && <div className="review-form"><div className="review-summary"><span className="review-symbol"><Sparkles /></span><div><h3>{title || t.eventName}</h3><p>{category || t.category}<i />{date}<i />{place || t.venue}</p></div></div><label className="form-field"><span>{t.description}</span><textarea value={description} onChange={(e) => setDescription(e.target.value)} placeholder={t.descriptionPlaceholder} rows={6} /></label><button className="ai-generate-button" onClick={createDescription} disabled={loading}>{loading ? <LoaderCircle className="spinning" /> : <WandSparkles />}{loading ? t.generating : t.generate}</button></div>}
    {error && <p className="form-error" role="alert"><CircleAlert />{error}</p>}<div className="wizard-footer">{step > 0 && <button className="button-outline" onClick={() => setStep((current) => Math.max(0,current - 1))}><ArrowRight />{t.previous}</button>}<span className="wizard-footer-note"><ShieldCheck />{t.draftInfo}</span>{step < 2 ? <button className="button-primary" onClick={continueStep}>{t.next}<ArrowLeft /></button> : <button className="button-primary" onClick={() => { onToast(t.submitted); setStep(0); setTitle(''); setDescription('') }}><Megaphone />{t.submit}</button>}</div></div></div><aside className="wizard-aside"><div className="aside-ai-art"><span><WandSparkles /></span><Sparkles className="aside-sparkle-one" /><Sparkles className="aside-sparkle-two" /><div className="aside-orbit orbit-one" /><div className="aside-orbit orbit-two" /></div><span className="eyebrow">{t.aiPowered}</span><h3>{t.generate}</h3><p>{ar ? 'صفي فكرتك، ودعي الذكاء الاصطناعي ينسج الكلمات.' : 'Share your idea, and let AI help tell its story.'}</p><div className="aside-benefits"><span><Check />{ar ? 'عربي وإنجليزي' : 'Arabic & English'}</span><span><Check />{ar ? 'نبرة جذابة للطلاب' : 'Engaging student tone'}</span><span><Check />{ar ? 'قابلة للتعديل' : 'Fully editable'}</span></div><div className="aside-tip"><Lightbulb /><span>{ar ? 'اختاري عنواناً واضحاً وجذاباً.' : 'Choose a clear, engaging title.'}</span></div></aside></div></div>
}

function CheckinPage({ t, ar, onToast }: any) {
  const [code, setCode] = useState('')
  const [result, setResult] = useState<'valid' | 'used' | 'invalid' | null>(null)
  const [checkedIn, setCheckedIn] = useState(false)
  function verify(value = code) { const id = value.trim().toUpperCase(); setResult(id === 'UE-2048' ? (checkedIn ? 'used' : 'valid') : id === 'UE-1592' ? 'used' : 'invalid') }
  function checkIn() { if (result === 'valid') { setCheckedIn(true); setResult('used'); onToast(t.checkedIn) } }
  return <div className="page-stack"><PageHeader eyebrow={t.organizerTools} title={t.checkTitle} description={t.checkSubtitle} action={<span className="live-status"><span />{t.scannerReady}</span>} /><div className="checkin-layout"><Card className="scanner-card"><div className="scanner-heading"><span className="scanner-icon"><ScanLine /></span><div><h2>{t.scan}</h2><p>{t.checkSubtitle}</p></div><Badge variant="secondary" className="demo-badge">{t.demo}</Badge></div><div className="scanner-preview"><div className="scanner-grid"><div className="scanner-corner corner-tl" /><div className="scanner-corner corner-tr" /><div className="scanner-corner corner-bl" /><div className="scanner-corner corner-br" /><span className="scanner-qr"><QrCode /></span><span className="scan-line" /></div><span className="scanner-preview-label"><span />{t.scannerReady}</span></div><div className="scanner-footnote"><ShieldCheck />{t.verifyInfo}</div></Card><Card className="manual-check-card"><span className="eyebrow"><span className="eyebrow-dot" />{t.manualCheck}</span><h2>{t.verify}</h2><p>{t.scanHint}</p><label className="form-field"><span>{t.ticketNumber}</span><div className="ticket-input-wrap"><QrCode /><input value={code} onChange={(e) => { setCode(e.target.value); setResult(null) }} onKeyDown={(e) => { if (e.key === 'Enter' && !e.nativeEvent.isComposing && e.keyCode !== 229) verify() }} placeholder={t.ticketSample} /><button onClick={() => verify()} aria-label={t.verify}><ArrowLeft /></button></div></label><button className="button-outline demo-code-button" onClick={() => { setCode('UE-2048'); setResult('valid') }}><Sparkles />{t.demoScan}</button>{result && <div className={`check-result result-${result}`} role="status"><span>{result === 'valid' ? <CircleCheck /> : result === 'used' ? <CheckCheck /> : <CircleAlert />}</span><div><strong>{t[result]}</strong><small>{result === 'valid' ? t.resultValid : result === 'used' ? t.resultUsed : t.resultInvalid}</small></div>{result === 'valid' && <button className="button-primary" onClick={checkIn}>{t.markAttendance}</button>}</div>}</Card></div><Card className="checkin-bottom-note"><span className="note-icon"><Lightbulb /></span><div><strong>{ar ? 'بدء سريع' : 'Quick start'}</strong><p>{t.scanHint} <kbd>UE-2048</kbd></p></div><span className="note-check"><Check /></span></Card></div>
}

const attendeeRows = [['سارة أحمد','2024011042','هندسة','حاضرة','صادرة'],['ليان محمد','2024012048','علوم الحاسب','حاضرة','صادرة'],['نور خالد','2024013120','إدارة الأعمال','مسجلة','—'],['جود إبراهيم','2024014578','علوم','حاضرة','صادرة'],['هند عبدالله','2024015093','آداب','مسجلة','—']]
function AttendeesPage({ t, ar, onToast }: any) {
  const [issued, setIssued] = useState(false)
  const [query, setQuery] = useState('')
  const visible = attendeeRows.filter((row) => row.join(' ').toLowerCase().includes(query.toLowerCase()))
  return <div className="page-stack"><PageHeader eyebrow={t.organizerTools} title={t.attendeesTitle} description={t.attendeeHint} action={<button className="button-outline" onClick={() => onToast(t.downloaded)}><Download />{t.export}</button>} /><div className="attendee-stats"><Metric icon={Users} label={t.registered} value="٢٢٤" change={t.thisWeek} /><Metric icon={CalendarCheck} label={t.attendance} value="٧٨٪" change="+١٢٪" /><Metric icon={FileText} label={t.certificates} value={issued ? '٢١٠' : '٠٠'} change={issued ? t.issued : t.pending} /></div><Card className="attendee-list-card"><div className="list-card-heading"><div><h2>{t.attendeeRowsTitle}</h2><p>{t.currentEntries}</p></div><div className="list-actions"><label className="list-search"><Search /><input placeholder={t.searchStudents} value={query} onChange={(e) => setQuery(e.target.value)} /></label><button className="button-outline" onClick={() => onToast(t.downloaded)}><Download />{t.export}</button></div></div><div className="table-scroll"><table className="attendee-table"><thead><tr><th>{t.student}</th><th>{t.studentId}</th><th>{t.college}</th><th>{t.status}</th><th>{t.certificate}</th></tr></thead><tbody>{visible.map(([name, id, college, status, cert], index) => <tr key={id}><td><span className="student-cell-avatar">{name[0]}</span>{ar ? name : t.studentRows[index]}</td><td dir="ltr">{id}</td><td>{ar ? college : t.collegeRows[index]}</td><td><span className={`table-status ${status === 'حاضرة' ? 'status-attended' : 'status-registered'}`}><i />{ar ? status : status === 'حاضرة' ? 'Attended' : 'Registered'}</span></td><td>{issued && status === 'حاضرة' ? <span className="certificate-issued"><Check />{t.issued}</span> : <span className="certificate-pending">{ar ? cert : cert === 'صادرة' ? 'Issued' : '—'}</span>}</td></tr>)}</tbody></table></div><div className="table-footer"><span>{ar ? `عرض ${visible.length} من ٢٢٤ طالبة` : `Showing ${visible.length} of 224 attendees`}</span><div><button className="pagination-button" aria-label={t.previous}><ChevronRight /></button><button className="pagination-current">1</button><button className="pagination-button" aria-label={t.next}><ChevronLeft /></button></div></div></Card><div className="issue-certificates-banner"><span className="issue-banner-icon"><FileText /></span><div><strong>{t.issueCertificates}</strong><p>{t.certificatesHint}</p></div><button className="button-primary" disabled={issued} onClick={() => { setIssued(true); onToast(t.issuedToast) }}><Sparkles />{issued ? t.issued : t.issue}</button></div></div>
}

function ApprovalsPage({ t, ar, onToast }: any) {
  const [pending, setPending] = useState([true, true])
  const [published, setPublished] = useState<number[]>([])
  const proposals = [{ title: 'مؤتمر الذكاء الاصطناعي للطلاب', en: 'Student AI Conference', category: 'تقنية', org: 'نادي علوم الحاسب', date: '٢٨ أكتوبر ٢٠٢٦', seats: '٢٥٠' },{ title: 'معرض المشاريع الريادية', en: 'Entrepreneurship Showcase', category: 'ريادة الأعمال', org: 'مركز ريادة الأعمال', date: '٣٠ أكتوبر ٢٠٢٦', seats: '١٨٠' }]
  const decide = (index: number, approved: boolean) => { setPending((current) => current.map((item, i) => index === i ? false : item)); onToast(approved ? t.approvedToast : t.rejectedToast) }
  return <div className="page-stack"><PageHeader eyebrow={t.adminTools} title={t.approveTitle} description={t.approveSubtitle} action={<span className="pending-pill"><span />{pending.filter(Boolean).length} {t.pendingItems}</span>} /><div className="approval-top-stats"><Metric icon={ShieldCheck} label={t.reviewQueue} value={String(pending.filter(Boolean).length).padStart(2,'0')} change={t.today} /><Metric icon={CalendarCheck} label={t.approved} value="١٨" change={t.thisWeek} /><Metric icon={Megaphone} label={t.channelsConnected} value="٣ / ٣" change={t.available} /></div><div className="approval-section-heading"><div><h2>{t.reviewQueue}</h2><p>{t.reviewTips}</p></div><Badge variant="secondary">{t.pending}</Badge></div><div className="approval-list">{proposals.map((proposal,index) => pending[index] && <Card key={proposal.title} className="approval-card"><span className="approval-icon"><CalendarDays /></span><div className="approval-content"><div className="approval-meta"><Badge variant="secondary">{ar ? proposal.category : proposal.category === 'تقنية' ? 'Technology' : 'Entrepreneurship'}</Badge><span>{proposal.date}</span></div><h3>{ar ? proposal.title : proposal.en}</h3><div className="approval-info"><span><Building2 />{proposal.org}</span><span><Users />{proposal.seats} {t.seats}</span><span><MapPin />{ar ? 'الحرم الجامعي' : 'University campus'}</span></div><p>{ar ? t.proposalText : 'A university gathering to explore new ideas and practical applications with the campus community.'}</p><div className="approval-actions"><button className="button-primary" onClick={() => decide(index,true)}><Check />{t.approve}</button><button className="button-outline reject-button" onClick={() => decide(index,false)}><X />{t.reject}</button><button className="text-button" onClick={() => onToast(t.details)}>{t.details}<ArrowLeft /></button></div></div><div className="approval-side"><span className="side-label">{t.channels}</span>{[['WhatsApp',MessageCircle],['Telegram',Send],['Facebook',Globe2]].map(([name, Icon]: any) => <label className="channel-option" key={name}><span className="channel-symbol"><Icon /></span><span>{ar ? name === 'WhatsApp' ? 'مجموعات واتساب' : name === 'Telegram' ? 'قنوات تيليجرام' : 'فيسبوك' : name}</span><input type="checkbox" defaultChecked={name !== 'Facebook'} aria-label={String(name)} /></label>)}<button className={`auto-publish-button ${published.includes(index) ? 'auto-published' : ''}`} onClick={() => { setPublished((current) => current.includes(index) ? current.filter((value) => value !== index) : [...current,index]); onToast(t.published) }}>{published.includes(index) ? <Check /> : <Megaphone />}{published.includes(index) ? t.published : t.publish}</button></div></Card>)}</div>{!pending.some(Boolean) && <div className="empty-state approval-empty"><span className="empty-art"><CircleCheck /></span><strong>{t.queueEmpty}</strong><span>{t.noPending}</span></div>}<div className="approval-tip"><ShieldCheck /><span>{t.privacy}</span><span>{t.dataDemo}</span></div></div>
}

const weeklyData = [{ name: 'الأحد', en: 'Sun', value: 182 },{ name: 'الاثنين', en: 'Mon', value: 236 },{ name: 'الثلاثاء', en: 'Tue', value: 198 },{ name: 'الأربعاء', en: 'Wed', value: 315 },{ name: 'الخميس', en: 'Thu', value: 267 },{ name: 'الجمعة', en: 'Fri', value: 158 },{ name: 'السبت', en: 'Sat', value: 224 }]
const collegesData = [{ name:'الهندسة',en:'Engineering',value:420 },{ name:'علوم الحاسب',en:'Computer Sci.',value:365 },{ name:'إدارة الأعمال',en:'Business',value:290 },{ name:'العلوم',en:'Science',value:210 },{ name:'الآداب',en:'Arts',value:165 }]
function AnalyticsPage({ t, ar }: any) {
  return <div className="page-stack"><PageHeader eyebrow={t.adminTools} title={t.analyticsTitle} description={t.analyticsSubtitle} action={<button className="button-outline"><CalendarDays />{t.period}<ChevronDown /></button>} /><div className="analytics-stats"><Metric icon={CalendarCheck} label={t.totalEvents} value={ar ? '١٨' : '18'} change="+٢٤٪" /><Metric icon={Users} label={t.registeredStudents} value={ar ? '١٬٢٨٠' : '1,280'} change="+١٨٪" /><Metric icon={Activity} label={t.attendance} value={ar ? '٧٨٪' : '78%'} change="+١٢٪" /><div className="rating-stat-card"><span className="rating-stat-icon"><Star /></span><span>{t.satisfaction}</span><div><strong>4.8</strong><span>/5</span><span className="rating-stars"><Star /><Star /><Star /><Star /><Star /></span></div><small><TrendingUp />+0.3 {t.registrationTrend}</small></div></div><div className="charts-grid"><Card className="chart-card attendance-chart"><div className="chart-heading"><div><span className="eyebrow"><span className="eyebrow-dot" />{t.thisWeek}</span><h2>{t.weekly}</h2><p>{t.dataDemo}</p></div><button className="icon-button" aria-label={t.other}><MoreHorizontal /></button></div><div className="chart-legend"><i />{t.attendance}<span>{ar ? '١٬٥٨٠' : '1,580'} {t.registered}</span></div><div className="chart-canvas" dir="ltr"><ResponsiveContainer width="100%" height="100%" initialDimension={{ width: 320, height: 176 }}><BarChart data={weeklyData} margin={{ top: 12, right: 8, left: -22, bottom: 0 }}><CartesianGrid vertical={false} stroke="var(--chart-grid)" strokeDasharray="4 5" /><XAxis dataKey={ar ? 'name' : 'en'} axisLine={false} tickLine={false} tick={{ fill: 'var(--muted-foreground)', fontSize: 11 }} dy={8} /><YAxis axisLine={false} tickLine={false} tick={{ fill: 'var(--muted-foreground)', fontSize: 11 }} ticks={[0,100,200,300,400]} /><Tooltip cursor={{ fill: 'var(--chart-hover)' }} contentStyle={{ borderRadius: 12, border: '1px solid var(--border)', background: 'var(--card)', color: 'var(--foreground)', fontSize: 12 }} /><Bar dataKey="value" fill="#6366f1" radius={[5,5,0,0]} maxBarSize={30} /></BarChart></ResponsiveContainer></div></Card><Card className="chart-card college-chart"><div className="chart-heading"><div><span className="eyebrow"><span className="eyebrow-dot" />{t.college}</span><h2>{t.byCollege}</h2><p>{t.dataDemo}</p></div><button className="icon-button" aria-label={t.other}><MoreHorizontal /></button></div><div className="college-list">{collegesData.map((college,index) => <div className="college-row" key={college.name}><div className="college-label"><span className={`college-rank rank-${index+1}`}>{`0${index+1}`}</span><span>{ar ? college.name : college.en}</span><strong>{college.value}</strong></div><Progress value={college.value/4.5} className={`college-progress progress-${index+1}`} aria-label={`${college.name}: ${college.value}`} /></div>)}</div><div className="college-footnote"><TrendingUp /><span>{t.analyticsTip}</span></div></Card></div><section className="sentiment-section"><div className="sentiment-header"><span className="sentiment-icon"><Sparkles /></span><div><span className="eyebrow">{t.aiPowered}</span><h2>{t.sentiment}</h2><p>{t.analyticsFeedback}</p></div><Badge variant="secondary" className="positive-badge"><span />{t.positive}</Badge></div><div className="sentiment-metrics"><div className="sentiment-score"><span>{t.satisfaction}</span><strong>4.8<small>/5</small></strong><span className="rating-stars"><Star /><Star /><Star /><Star /><Star /></span><small>{t.sentimentText}</small></div><div className="sentiment-bars"><span>{t.overall}</span><div className="sentiment-bar-row"><span>{ar ? 'إيجابي' : 'Positive'}</span><div className="sentiment-track"><i style={{ width: '92%' }} /></div><strong>92%</strong></div><div className="sentiment-bar-row"><span>{ar ? 'محايد' : 'Neutral'}</span><div className="sentiment-track neutral-track"><i style={{ width: '6%' }} /></div><strong>6%</strong></div><div className="sentiment-bar-row"><span>{ar ? 'سلبي' : 'Negative'}</span><div className="sentiment-track negative-track"><i style={{ width: '2%' }} /></div><strong>2%</strong></div></div><div className="sentiment-insight"><span><Sparkles /></span><div><strong>{t.smartSummary}</strong><p>{t.analyticsTip}</p></div><ArrowLeft /></div></div></section><div className="analytics-footer"><span><ShieldCheck />{t.privacy}</span><span>{t.dataDemo}</span><button className="text-button">{t.report}<Download /></button></div></div>
}

function ChatPanel({ t, ar, messages, input, setInput, loading, onSend, onClose }: any) {
  const suggestions = [t.q1,t.q2,t.q3]
  function submit(event: FormEvent) { event.preventDefault(); onSend() }
  return <><button className="chat-scrim" aria-label={t.close} onClick={onClose} /><aside className="chat-panel" dir={ar ? 'rtl' : 'ltr'} aria-label={t.assistant}><div className="chat-header"><span className="chat-avatar"><Sparkles /></span><div><strong>{t.assistant}</strong><small><span />{ar ? 'متصل' : 'Available'}</small></div><button className="icon-button" onClick={onClose} aria-label={t.close}><X /></button></div><div className="chat-intro"><span className="chat-intro-icon"><Sparkles /></span><strong>{t.assistantIntro}</strong><span>{t.aiIntro}</span></div><div className="chat-suggestions">{suggestions.map((item: string) => <button key={item} onClick={() => onSend(item)}>{item}<ArrowUpLeft /></button>)}</div><div className="chat-messages" aria-live="polite">{messages.map((message: any,index: number) => <div className={`chat-message ${message.role}`} key={`${message.role}-${index}`}><span>{message.text}</span></div>)}{loading && <div className="chat-message assistant"><span className="typing-dots"><i /><i /><i /></span></div>}</div><form className="chat-composer" onSubmit={submit}><input value={input} onChange={(event) => setInput(event.target.value)} placeholder={t.assistantHint} aria-label={t.assistantHint} /><button type="submit" disabled={loading || !input.trim()} aria-label={t.send}><Send /></button><small>{t.aiPowered}</small></form></aside></>
}
